G0=json.loads((S/'F063_frozen_target_geometry.json').read_text());T=np.array(G0['T_target']);L=np.array(G0['L_target']);G=np.array(G0['G_target']);srT=np.array([505.,717.]);srL=np.array([1190.,609.]);v=srL-srT;u=L-T;sc=np.linalg.norm(u)/np.linalg.norm(v);ang=math.atan2(u[1],u[0])-math.atan2(v[1],v[0]);M=sc*np.array([[math.cos(ang),-math.sin(ang)],[math.sin(ang),math.cos(ang)]]);t=T-M@srT;inv=np.linalg.inv(M);it=-inv@t
